from pathlib import Path
from typing import Final

import pytest

NOTES_DIR: Final[Path] = Path("notes")


def note_path(name: str) -> Path | None:
    """Return the path of `name` inside NOTES_DIR, or None if it falls outside.

    Rejects absolute names, names whose ".." components leave NOTES_DIR,
    and symlinks that resolve to a location outside NOTES_DIR.
    """
    if not name or Path(name).is_absolute():
        return None
    try:
        base = NOTES_DIR.resolve()
        candidate = (base / name).resolve()
    except (OSError, ValueError):
        return None
    if candidate == base:
        return None
    try:
        candidate.relative_to(base)
    except ValueError:
        return None
    return candidate


def is_readable_note(name: str) -> bool:
    """True when `name` is a regular file inside NOTES_DIR that can be read."""
    path = note_path(name)
    if path is None or not path.is_file():
        return False
    try:
        with path.open("rb"):
            return True
    except OSError:
        return False


def read_note(name: str) -> str:
    """Return the text of note `name`.

    Returns "" when the file is missing, unreadable, a directory, or outside NOTES_DIR.
    """
    path = note_path(name)
    if path is None or not path.is_file():
        return ""
    try:
        return path.read_text(encoding="utf-8")
    except (OSError, ValueError):
        return ""


def count_readable(names: list[str]) -> int:
    """Count how many entries of `names` are readable files inside NOTES_DIR.

    Untrusted names must never cause a read outside NOTES_DIR.
    """
    return sum(1 for name in names if is_readable_note(name))


@pytest.fixture
def notes_dir(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    """Create tmp_path/notes with a.txt and b.txt, and chdir into tmp_path."""
    notes = tmp_path / "notes"
    notes.mkdir()
    (notes / "a.txt").write_text("alpha", encoding="utf-8")
    (notes / "b.txt").write_text("beta", encoding="utf-8")
    monkeypatch.chdir(tmp_path)
    return notes


def test_counts_existing_files(notes_dir: Path) -> None:
    assert count_readable(["a.txt", "b.txt", "c.txt"]) == 2


def test_empty_list_is_zero(notes_dir: Path) -> None:
    assert count_readable([]) == 0


def test_empty_readable_file_is_counted(notes_dir: Path) -> None:
    (notes_dir / "empty.txt").write_text("", encoding="utf-8")
    assert count_readable(["empty.txt"]) == 1


def test_directory_is_not_counted(notes_dir: Path) -> None:
    (notes_dir / "sub").mkdir()
    assert count_readable(["sub"]) == 0


def test_relative_traversal_is_rejected(notes_dir: Path, tmp_path: Path) -> None:
    (tmp_path / "secret.txt").write_text("hidden", encoding="utf-8")
    assert count_readable(["../secret.txt", "sub/../../secret.txt"]) == 0


def test_absolute_path_is_rejected(notes_dir: Path, tmp_path: Path) -> None:
    secret = tmp_path / "secret.txt"
    secret.write_text("hidden", encoding="utf-8")
    assert count_readable([str(secret)]) == 0


def test_dotdot_that_stays_inside_is_allowed(notes_dir: Path) -> None:
    assert count_readable(["sub/../a.txt"]) == 1


def test_symlink_escaping_notes_is_rejected(notes_dir: Path, tmp_path: Path) -> None:
    secret = tmp_path / "secret.txt"
    secret.write_text("hidden", encoding="utf-8")
    (notes_dir / "link.txt").symlink_to(secret)
    assert count_readable(["link.txt"]) == 0


def test_symlink_inside_notes_is_counted(notes_dir: Path) -> None:
    (notes_dir / "alias.txt").symlink_to(notes_dir / "a.txt")
    assert count_readable(["alias.txt"]) == 1


def test_read_note_returns_content(notes_dir: Path) -> None:
    assert read_note("a.txt") == "alpha"


def test_read_note_missing_is_empty(notes_dir: Path) -> None:
    assert read_note("nope.txt") == ""


def test_read_note_traversal_is_empty(notes_dir: Path, tmp_path: Path) -> None:
    (tmp_path / "secret.txt").write_text("hidden", encoding="utf-8")
    assert read_note("../secret.txt") == ""


def test_note_path_rejects_escape(notes_dir: Path) -> None:
    assert note_path("../secret.txt") is None
    assert note_path("a.txt") is not None


def test_is_readable_note(notes_dir: Path) -> None:
    assert is_readable_note("a.txt") is True
    assert is_readable_note("missing.txt") is False
